#!/usr/bin/env node
/* eslint-disable @typescript-eslint/no-var-requires */
/**
 * Generates src/wallet/privy.config.generated.ts from environment variables.
 *
 * Why: the Privy App ID is hardcoded in the SDK at build time but MUST NOT
 * appear in any git diff. This script reads PRIVY_APP_ID from process.env
 * (loaded from .env locally, or from CI secrets) and writes a typed
 * .gitignored file that the SDK imports.
 *
 * Behaviour:
 * - If PRIVY_APP_ID is set, writes the real value.
 * - If unset AND the generated file already exists, do nothing (idempotent).
 * - If unset AND no generated file, writes a placeholder so the TypeScript
 *   build succeeds in environments without Privy configured (tests, OSS-style
 *   builds). The runtime will refuse to initialize Privy with the placeholder.
 */

const fs = require("fs");
const path = require("path");

const OUTPUT_PATH = path.join(__dirname, "..", "src", "wallet", "privy.config.generated.ts");
const PLACEHOLDER = "__PRIVY_APP_ID_NOT_SET__";

// Defensive guard: if we are being run outside the SDK source tree (for
// example, accidentally invoked as a postinstall hook inside a consumer's
// node_modules where only `dist/` is shipped), exit silently. The published
// package never needs to (re)generate this file — the value is already baked
// into the compiled JS.
if (!fs.existsSync(path.join(__dirname, "..", "src", "wallet"))) {
  process.exit(0);
}

function loadDotenv() {
  const envPath = path.join(__dirname, "..", ".env");
  if (!fs.existsSync(envPath)) return;
  const lines = fs.readFileSync(envPath, "utf-8").split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq <= 0) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    if (!(key in process.env)) {
      process.env[key] = value;
    }
  }
}

loadDotenv();

const appId = process.env.PRIVY_APP_ID || "";

if (!appId) {
  if (fs.existsSync(OUTPUT_PATH)) {
    console.log("[generate-privy-config] PRIVY_APP_ID ausente, mantendo arquivo existente.");
    process.exit(0);
  }
  console.warn(
    "[generate-privy-config] PRIVY_APP_ID ausente — gerando placeholder. " +
      "Wallet service não inicializará em runtime.",
  );
}

// Emit single-quoted strings to satisfy the eslint quotes rule in this repo.
const sq = (value) => "'" + String(value).replace(/\\/g, "\\\\").replace(/'/g, "\\'") + "'";

// Explicit `: string` annotations widen the literal type, so call sites like
// `PRIVY_APP_ID !== PRIVY_PLACEHOLDER` don't get flagged as "always true" by
// TypeScript when both sides are different literal constants.
const content =
  "// AUTO-GENERATED by scripts/generate-privy-config.js — DO NOT EDIT MANUALLY.\n" +
  "// This file is gitignored. The PRIVY_APP_ID is injected from env at build time.\n" +
  "export const PRIVY_APP_ID: string = " +
  sq(appId || PLACEHOLDER) +
  ";\n" +
  "export const PRIVY_PLACEHOLDER: string = " +
  sq(PLACEHOLDER) +
  ";\n";

fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
fs.writeFileSync(OUTPUT_PATH, content, "utf-8");

console.log("[generate-privy-config] Wrote " + OUTPUT_PATH + " (appId=" + (appId ? "<set>" : "<placeholder>") + ")");
